#![forbid(unsafe_code)]

use serde::{Deserialize, Serialize};
use std::collections::BTreeMap;

/// Represents an injected executable artifact generated by a constructive meta-layer
/// (as formulated in Meta^n: Recursive Self-Improvement through Emergent Depth).
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct InjectedCode {
    /// Injected pre-process or normalization hook script.
    pub pre_process: Option<String>,
    /// Injected code utilities / helper functions library (`dict` of function name to code).
    pub code_library: BTreeMap<String, String>,
    /// System directives or avoidance invariants constructed from lower layer traces.
    pub directives: Vec<String>,
}

/// A meta-layer $M_k$ wrapping inner layers $M_{k-1} \dots M_1(S_0)$.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct MetaLayer {
    /// Depth order (0 = base executor, 1 = solver, 2+ = emergent meta-layers).
    pub order: u32,
    /// Identifier for this meta-layer.
    pub layer_id: String,
    /// The constructive code artifacts injected into the execution flow.
    pub injected: InjectedCode,
    /// Empirical score achieved by this stacked layer.
    pub score: f64,
    /// Reason or motivation for this layer's emergence from lower traces.
    pub emergence_rationale: String,
}

/// Fixed-point termination status ($\Omega$) when successive meta-layers reach convergence.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct FixedPointOmega {
    /// True if the meta-improvement has reached fixed-point convergence $M(\mathcal{P}^*) = \mathcal{P}^*$.
    pub converged: bool,
    /// The order $N$ at which convergence was reached.
    pub convergence_depth: u32,
    /// The score delta between the final two meta-orders.
    pub epsilon_delta: f64,
    /// Description of the fixed-point attractor state.
    pub attractor_state: String,
}

/// Monotonically growing Candidate Archive and Emergent Depth Stack.
#[derive(Clone, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct EmergentDepthStack {
    /// Stack of active meta-layers ordered from innermost (order 0) to outermost (order N).
    pub layers: Vec<MetaLayer>,
    /// Convergence state under fixed-point termination criteria.
    pub fixed_point: Option<FixedPointOmega>,
}

impl EmergentDepthStack {
    pub fn new() -> Self {
        Self {
            layers: Vec::new(),
            fixed_point: None,
        }
    }

    pub fn current_depth(&self) -> u32 {
        self.layers.last().map(|l| l.order).unwrap_or(0)
    }

    pub fn push_layer(&mut self, layer: MetaLayer) {
        self.layers.push(layer);
    }

    /// Checks if adding a new score meets the fixed point termination threshold $\epsilon$.
    pub fn check_fixed_point(&mut self, epsilon: f64) -> bool {
        if self.layers.len() < 2 {
            return false;
        }
        let n = self.layers.len();
        let last_score = self.layers[n - 1].score;
        let prev_score = self.layers[n - 2].score;
        let delta = (last_score - prev_score).abs();

        if delta < epsilon {
            self.fixed_point = Some(FixedPointOmega {
                converged: true,
                convergence_depth: self.current_depth(),
                epsilon_delta: delta,
                attractor_state: format!(
                    "Meta-layer depth reached fixed-point at order {} with delta {:.5} < threshold {:.5}",
                    self.current_depth(),
                    delta,
                    epsilon
                ),
            });
            true
        } else {
            false
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_emergent_depth_fixed_point_convergence() {
        let mut stack = EmergentDepthStack::new();
        stack.push_layer(MetaLayer {
            order: 1,
            layer_id: "layer-1-solver".to_string(),
            injected: InjectedCode::default(),
            score: 0.767,
            emergence_rationale: "Initial base solver".to_string(),
        });
        stack.push_layer(MetaLayer {
            order: 2,
            layer_id: "layer-2-fuzzy-matcher".to_string(),
            injected: InjectedCode::default(),
            score: 0.833,
            emergence_rationale: "Injected fuzzy matcher helper".to_string(),
        });

        // Delta is 0.066, not converged for epsilon=0.01
        assert!(!stack.check_fixed_point(0.01));

        stack.push_layer(MetaLayer {
            order: 3,
            layer_id: "layer-3-refinement".to_string(),
            injected: InjectedCode::default(),
            score: 0.835,
            emergence_rationale: "Prompt normalization rollback".to_string(),
        });

        // Delta is 0.002 < 0.01 -> converged to Omega!
        assert!(stack.check_fixed_point(0.01));
        assert!(stack.fixed_point.as_ref().unwrap().converged);
        assert_eq!(stack.fixed_point.as_ref().unwrap().convergence_depth, 3);
    }
}
